        'upsert 0 user "hello"',
        'upsert 1 assistant ""',
        'delta 1 "leaked"',
        'commit 1',
        'upsert 1 assistant ""',
        'stream_end',
      ]);
    });

    it('never blanks a thinking entry, only assistant ones', async () => {
